namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public int LoyaltyPart(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, CapCents);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
EOF
cat > CheckoutPricing.Domain/PromoCodePolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public sealed class PromoCodePolicy
{
    private const int WelcomeCents = 500;
    private const int SummerCapCents = 1_500;

    public int Discount(string? code, int remainingCents) =>
        code?.ToUpperInvariant() switch
        {
            "WELCOME5" => WelcomeCents,
            "SUMMER10" => Math.Min(remainingCents / 10, SummerCapCents),
            _ => 0
        };
}
EOF
cat > CheckoutPricing.Domain/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public sealed class DiscountPolicy
{
    private readonly LoyaltyDiscountPolicy loyalty = new();
    private readonly PromoCodePolicy promo = new();

    public int Discount(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = loyalty.LoyaltyPart(subtotalCents, tier);
        var promoPart = promo.Discount(promoCode, subtotalCents - loyaltyPart);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }
}
EOF
cat > CheckoutPricing.Domain/ShippingPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public sealed class ShippingPolicy
{
    private const int StandardCents = 490;
    private const int ExpressCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public int Fee(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express ? ExpressFee(tier) : StandardFee(payableTotalCents, tier);

    private static int ExpressFee(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressCents;

    private static int StandardFee(int payableTotalCents, LoyaltyTier tier) =>
        payableTotalCents >= FreeStandardFromCents || tier >= LoyaltyTier.Gold ? 0 : StandardCents;
}
EOF
